   312→  /**
   313→   * 연산자 토큰화
   314→   */
   315→  private tokenizeOperator(): Token | null {
   316→    const ch = this.peek();
   317→    const next = this.peek(1);
   318→    const next2 = this.peek(2);
   319→
   320→    // 3글자 연산자
   321→    if (ch === '.' && next === '.' && next2 === '=') {
   322→      this.advance();
   323→      this.advance();
   324→      this.advance();
