   385→  /**
   386→   * @mode() 디렉티브 파싱
   387→   */
   388→  private tryParseMode(): Token | null {
   389→    const start = this.pos;
   390→
   391→    if (this.peek() !== '@') {
   392→      return null;
   393→    }
   394→
   395→    this.advance(); // '@'
   396→
   397→    // @mode 확인
   398→    if (
   399→      this.peek() === 'm' &&
   400→      this.peek(1) === 'o' &&
   401→      this.peek(2) === 'd' &&
   402→      this.peek(3) === 'e'
   403→    ) {
   404→      this.advance();
   405→      this.advance();
   406→      this.advance();
   407→      this.advance();
   408→
   409→      // 공백 및 ( 확인
   410→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   411→        this.advance();
   412→      }
   413→
   414→      if (this.peek() !== '(') {
   415→        // @mode가 아니면 다시 돌아가기
   416→        this.pos = start;
   417→        return null;
   418→      }
   419→
   420→      this.advance(); // '('
   421→
   422→      // 공백
   423→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   424→        this.advance();
   425→      }
   426→
   427→      // v 또는 python 확인
   428→      let mode: 'v' | 'python' | null = null;
   429→
   430→      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
   431→        mode = 'v';
   432→        this.advance();
   433→      } else if (
   434→        this.peek() === 'p' &&
   435→        this.peek(1) === 'y' &&
   436→        this.peek(2) === 't' &&
   437→        this.peek(3) === 'h' &&
   438→        this.peek(4) === 'o' &&
   439→        this.peek(5) === 'n'
   440→      ) {
   441→        mode = 'python';
   442→        this.advance();
   443→        this.advance();
   444→        this.advance();
   445→        this.advance();
   446→        this.advance();
   447→        this.advance();
   448→      }
   449→
   450→      if (!mode) {
   451→        // 유효한 모드가 아니면 다시 돌아가기
   452→        this.pos = start;
   453→        return null;
   454→      }
   455→
   456→      // 공백 및 ) 확인
   457→      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
   458→        this.advance();
   459→      }
   460→
   461→      if (this.peek() !== ')') {
   462→        this.pos = start;
   463→        return null;
   464→      }
   465→
   466→      this.advance(); // ')'
   467→
   468→      // 모드 전환!
   469→      this.currentMode = mode;
   470→
   471→      const value = this.source.substring(start, this.pos);
   472→      return this.makeToken(TokenType.MODE_MARKER, value, mode);
   473→    }
   474→
   475→    this.pos = start;
   476→    return null;
   477→  }
